#[test]
fn test_bhv_errors_004_api_error_exposes_status_message_body_headers() {
    let mut headers = HashMap::new();
    headers.insert("content-type".to_string(), "application/json".to_string());

    let err = ApiError::new(
        404,
        "not found".to_string(),
        Some(headers),
        Some(r#"{"id":7,"name":"missing"}"#.to_string()),
    );

    assert_eq!(err.status_code(), 404);
    assert_eq!(err.message(), "not found");
    assert_eq!(err.response_body(), Some(r#"{"id":7,"name":"missing"}"#));
    assert_eq!(
        err.response_headers()
            .as_ref()
            .unwrap()
            .get("content-type")
            .unwrap(),
        "application/json"
    );
    // The parsed-JSON view of the body is a crate-internal detail; the public
    // surface is `typed_error_body`, which deserializes the raw body on demand.
    let typed: Option<Category> = err.typed_error_body().expect("body is valid JSON");
    assert_eq!(typed.expect("expected Some(Category)").id, Some(7));
}

