/// A status-specific error reports the request method and path it answers, through its wrapper chain.
#[test]
fn test_bhv_errors_002_every_status_error_carries_the_request_context() {
    let api = ApiError::new(404, "missing".to_string(), None, None)
        .with_request("GET", "/items/7?token=x");
    let not_found =
        NotFoundError::try_from(ClientError::try_from(api).expect("a 4xx")).expect("a 404");
    assert_eq!(
        not_found.client_error().api_error().request_method(),
        Some("GET")
    );
    assert_eq!(
        not_found.client_error().api_error().request_path(),
        Some("/items/7")
    );

    let api =
        ApiError::new(500, "boom".to_string(), None, None).with_request("POST", "/orders?id=1");
    let internal =
        InternalServerError::try_from(ServerError::try_from(api).expect("a 5xx")).expect("a 500");
    assert_eq!(
        internal.server_error().api_error().request_method(),
        Some("POST")
    );
    assert_eq!(
        internal.server_error().api_error().request_path(),
        Some("/orders")
    );
}

/// A status-specific error keeps the optional cause it was built with, and reaches it through its source chain.
#[test]
fn test_bhv_errors_003_status_specific_errors_keep_an_optional_cause() {
    let cause: std::sync::Arc<dyn std::error::Error + Send + Sync> =
        std::sync::Arc::new(std::io::Error::other("socket reset"));
    let with_cause = ApiError::with_source(404, "missing".to_string(), None, None, cause);
    let not_found =
        NotFoundError::try_from(ClientError::try_from(with_cause).expect("a 4xx")).expect("a 404");
    let chain_has_cause = std::iter::successors(
        Some(&not_found as &(dyn std::error::Error + 'static)),
        |e| e.source(),
    )
    .any(|e| e.downcast_ref::<std::io::Error>().is_some());
    assert!(
        chain_has_cause,
        "the cause must be reachable from the status error"
    );

    let plain = ApiError::new(404, "missing".to_string(), None, None);
    let plain_error =
        NotFoundError::try_from(ClientError::try_from(plain).expect("a 4xx")).expect("a 404");
    let plain_has_cause = std::iter::successors(
        Some(&plain_error as &(dyn std::error::Error + 'static)),
        |e| e.source(),
    )
    .any(|e| e.downcast_ref::<std::io::Error>().is_some());
    assert!(
        !plain_has_cause,
        "a status error built without a cause has none"
    );
}

